  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Nutrients and MyPlate$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Food is fuel and building material for the body. Nutrients are the substances in food that the body needs. There are six kinds. Carbohydrates are the main source of quick energy and come from grains, fruits, vegetables and dairy. Proteins build and repair muscle and other tissue and come from meat, fish, eggs, dairy, beans and nuts. Fats supply long lasting energy, protect organs and help the body use some vitamins, and healthy fats come from fish, nuts, seeds, olive oil and avocados. Vitamins and minerals help the body work and are needed in small amounts. Water is needed for almost every body process.\n\nEnergy in food is measured in calories. A gram of carbohydrate or protein supplies about 4 calories and a gram of fat supplies about 9. Growing teens who are active need enough food to fuel their bodies, and each person's needs are different, so they should not copy anyone else's plan.\n\nThe government's MyPlate guide shows a plate divided into fruits, vegetables, grains and protein, with a serving of dairy on the side. A helpful guide is to fill about half your plate with fruits and vegetables, choose whole grains, vary your protein, and choose water and milk more often than sugary drinks. Genesis 1:29 records that God gave plants and fruit for food. Proverbs 25:16 teaches moderation: Hast thou found honey? eat so much as is sufficient for thee, lest thou be filled therewith, and vomit it.\n\nEating a variety of foods, including colorful fruits and vegetables, gives the body the nutrients it needs. Eat breakfast, and plan regular meals and snacks so that your body and mind stay fueled through the day.\n\nYour task: (1) Name the six kinds of nutrients and a job for each. (2) Describe what a MyPlate meal looks like. (3) Plan a day of meals and snacks using the five food groups.\n\nFlorida standards: PE.912.L.3, HE.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, HE.912.C.1", "script": "Welcome back. Listen, the food on your plate is fuel and building material. Today we learn how to choose it.\n\nThere are six kinds of nutrients. Carbohydrates give quick energy. Proteins build and repair muscle and other tissue. Fats supply lasting energy and protect organs. Vitamins and minerals help the body work. And water, which is needed for almost every process in the body.\n\nNow watch this. Energy in food is measured in calories. A gram of carbohydrate or protein gives about four calories. A gram of fat gives about nine. Active, growing teens need enough food to fuel their bodies, and each person is different, so do not copy someone else's plan.\n\nLook at MyPlate. Think of a plate with fruits, vegetables, grains and protein, and dairy on the side. Fill about half your plate with fruits and vegetables, choose whole grains, vary your protein, and choose water and milk more often than sugary drinks.\n\nGenesis 1:29 shows that God provided plants and fruit for food. And Proverbs 25:16 teaches moderation. Eat so much as is sufficient for thee.\n\nEat breakfast and plan regular meals and snacks to keep your body and mind fueled.\n\nYour task is to name the six nutrients, describe a MyPlate meal and plan a day of meals. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Nutrients and MyPlate$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Reading Food Labels$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "The Nutrition Facts label on packaged food helps you choose wisely. Start at the top with the serving size. All the numbers on the label are for one serving, and many packages hold more than one. If you eat two servings, you take in twice the calories and nutrients shown.\n\nNext, look at the calories and the amounts of key nutrients. Try to limit added sugars, saturated fat and sodium, which is the salt in food. Too much of these over time can contribute to heart disease, high blood pressure and other problems. Try to get enough fiber, vitamin D, calcium, iron and potassium. The Percent Daily Value, shown as a percent, tells how much a serving contributes to a daily diet. As a general guide, 5 percent or less is low and 20 percent or more is high. Choose foods higher in fiber and vitamins and lower in added sugars, saturated fat and sodium.\n\nRead the ingredient list too. Ingredients are listed from the greatest amount to the least, so if sugar is first, the food has more sugar than anything else. Sugar goes by many names, such as corn syrup, fructose and cane juice. Sweetened drinks, soda, sports drinks and energy drinks can carry a lot of sugar, and energy drinks may carry large amounts of caffeine, which health experts advise teens to avoid.\n\nBe wise about marketing. Words such as natural, light or energy on the front of a package do not always mean the food is healthy. Proverbs 23:20 warns, Be not among winebibbers; among riotous eaters of flesh. Wisdom means making careful choices rather than following every craving or advertisement.\n\nYour task: (1) Explain where to begin when reading a Nutrition Facts label and why. (2) Compare two snack labels and tell which is the better choice and why. (3) Explain what Percent Daily Value means.\n\nFlorida standards: PE.912.L.3, HE.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, HE.912.C.1", "script": "Welcome back. Listen, the front of a package is an advertisement. The back is the truth. Learn to read the label.\n\nStart at the top with the serving size. All the numbers are for one serving, and many packages hold more than one. Eat two servings and you take in double.\n\nNow watch this. Look at the calories and key nutrients. Try to limit added sugars, saturated fat and sodium, which is salt. Too much over time can contribute to heart disease and high blood pressure. Try to get enough fiber, vitamin D, calcium, iron and potassium. The Percent Daily Value tells how much a serving adds to a daily diet. A good guide is that 5 percent or less is low, and 20 percent or more is high.\n\nLook at the ingredient list. Ingredients are listed from the greatest amount to the least. If sugar is first, there is more sugar than anything else. Sugar goes by many names, like corn syrup and fructose.\n\nBe careful with soda, sports drinks and energy drinks. They can carry a lot of sugar. Energy drinks can carry a lot of caffeine, and health experts advise teens to avoid them.\n\nWords like natural or energy on the front do not always mean healthy. Proverbs 23:20 says, Be not among winebibbers; among riotous eaters of flesh. Make careful choices.\n\nYour task is to explain where to begin on a label, compare two snack labels, and explain Percent Daily Value. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Reading Food Labels$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Fueling and Hydration for Activity$j$, $j${"readings": [{"title": "Daniel 1 (King James Version)", "url": "/portal/bible/Daniel/1"}], "body": "Water makes up more than half of the body and is needed for temperature control, digestion, joints and every cell. When you exercise, you lose water through sweat, and even mild dehydration can cause tiredness, headache, poor focus, cramps and slower performance. In Florida heat, the risk grows.\n\nHydration is simple. Drink water regularly through the day. Drink a glass of water about an hour or two before heavy activity, sip water during activity, and drink again afterward. A good check is urine color. Pale yellow suggests good hydration, and dark yellow suggests you need more fluid. Do not wait until you feel thirsty. For most activities that last under an hour, water is the best choice. Sports drinks may help during very long or very hot activity, but they carry sugar, and most students do not need them. Avoid energy drinks. Also avoid drinking huge amounts of water at once.\n\nFuel the body too. A meal with carbohydrates, some protein and little fat about 2 to 3 hours before hard activity gives energy. A small snack such as a banana or a piece of toast with peanut butter can be eaten an hour before. After activity, a snack or meal with carbohydrates and protein, such as milk and fruit or a turkey sandwich, helps muscles recover.\n\nDaniel 1:12 records Daniel's request, Prove thy servants, I beseech thee, ten days; and let them give us pulse to eat, and water to drink. After ten days, Daniel and his friends looked healthier than those who ate the king's rich food. Good food and water are gifts that sustain strength.\n\nYour task: (1) Explain three effects of dehydration. (2) Make a hydration plan for a day with afterschool practice. (3) Plan a pre activity and post activity snack.\n\nFlorida standards: PE.912.L.3, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, PE.912.R.5", "script": "Welcome back. Listen, more than half of your body is water, and in South Florida you lose a lot of it when you move.\n\nWater controls your temperature, helps digestion, cushions your joints and serves every cell. When you sweat, you lose water. Even mild dehydration can cause tiredness, headache, poor focus, cramps and slower performance.\n\nNow watch this. Here is how to stay hydrated. Drink water regularly through the day. Drink a glass an hour or two before heavy activity. Sip during activity. Drink again afterward. Check your urine color. Pale yellow is good. Dark yellow says drink more. Do not wait until you feel thirsty. For most activities under an hour, water is the best choice. Sports drinks carry sugar, and most students do not need them. Avoid energy drinks.\n\nLook at fuel. A meal with carbohydrates, some protein and little fat two to three hours before hard activity gives energy. A banana or toast with peanut butter works an hour before. Afterward, carbohydrates and protein, like milk and fruit, help your muscles recover.\n\nIn Daniel 1:12, Daniel asked for pulse to eat and water to drink, and after ten days he and his friends looked healthier than the others. Good food and water sustain strength.\n\nYour task is to explain three effects of dehydration, make a hydration plan and plan two snacks. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Fueling and Hydration for Activity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Healthy Habits, Body Image and Supplements$j$, $j${"readings": [{"title": "1 Corinthians 10 (King James Version)", "url": "/portal/bible/1Corinthians/10"}], "body": "Healthy eating is a lifelong habit, not a short diet. Fad diets, cleanses and quick fix plans that promise fast weight change are often unsafe, and the weight usually returns. Teens are still growing, so they need regular meals with enough food to fuel growth, learning and activity. First Corinthians 10:31 says, Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.\n\nBody image is how you think and feel about your body. Social media, ads and filtered photos can make unrealistic bodies seem normal. A body is not good or bad by its size or shape. Psalm 139:14 says that you are fearfully and wonderfully made. Focus on what your body can do, how it feels and how well you care for it. Avoid teasing, comments about other people's bodies and constant comparison.\n\nSome people develop an eating disorder, a serious illness that affects eating and thinking and can harm the body and the mind. Warning signs can include obsessing about food, weight or body shape, skipping meals or refusing to eat in front of others, eating in secret, extreme exercise, hiding the body, mood changes, or purging. Eating disorders are medical conditions and not a choice, and they can be treated. A student who is worried about themselves or a friend should speak with a trusted adult, a parent, a school counselor, a pastor or a doctor, and encourage a friend to do the same. Help is available and recovery is possible.\n\nBe careful with supplements. Protein powders, fat burners, pre workout products and muscle builders are not tested like medicines, may contain harmful or unlisted ingredients, and are not a safe shortcut for a growing teen. Anabolic steroids and other performance enhancing drugs can damage the heart, liver and mind. Ask a doctor before taking any supplement.\n\nYour task: (1) Explain why fad diets and quick fixes are unsafe for teens. (2) Describe a healthy view of the body and how to speak kindly about bodies. (3) Tell what a student should do if they are worried about their own or a friend's eating.\n\nFlorida standards: HE.912.C.1, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, PE.912.R.5", "script": "Welcome back. Listen, this is an important lesson, and I want you to hear it with your heart.\n\nHealthy eating is a lifelong habit, not a short diet. Fad diets, cleanses and quick fixes that promise fast change are often unsafe, and the weight usually returns. Teens are still growing, so you need regular meals with enough food to fuel growth, learning and activity. First Corinthians 10:31 says, whether ye eat, or drink, or whatsoever ye do, do all to the glory of God.\n\nNow watch this. Body image is how you think and feel about your body. Social media, ads and filtered photos can make unrealistic bodies look normal. A body is not good or bad because of its size or shape. Psalm 139:14 says you are fearfully and wonderfully made. Focus on what your body can do and how well you care for it. Do not tease and do not compare.\n\nLook at this carefully. An eating disorder is a serious medical illness. Warning signs include obsessing about food, weight or shape, skipping meals, eating in secret, extreme exercise and hiding the body. If you are worried about yourself or a friend, talk to a trusted adult, a parent, a school counselor, a pastor or a doctor. Help is available and recovery is possible.\n\nFinally, be careful with supplements. Protein powders, fat burners and pre workout products are not tested like medicines and can be harmful. Steroids damage the heart, liver and mind. Ask a doctor first.\n\nYour task is to explain why fad diets are unsafe, describe a healthy view of the body, and tell what to do if you are worried. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Healthy Habits, Body Image and Supplements$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Nutrition and Hydration$j$, $j${"prompt": "Write a report of at least 250 words on nutrition and hydration. Use complete sentences and label each part. First Corinthians 10:31 says, Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.\n\nPart 1: Name the six kinds of nutrients and explain the job of each.\nPart 2: Describe a healthy MyPlate meal and plan one full day of meals and snacks.\nPart 3: Choose two packaged snacks, compare their Nutrition Facts labels and tell which is the better choice and why.\nPart 4: Make a hydration and fueling plan for a day with physical activity in the Florida heat.\nPart 5: Explain why fad diets and supplements are unsafe for teens, describe a healthy view of the body, and tell where a student can find help if worried about eating habits.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Nutrition and Hydration$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Food, Water and Self Worth$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells one change you will make to eat or drink more wisely, (2) explains how social media or advertising can affect how teens see their bodies, (3) describes one way to encourage a friend who is struggling with body image or eating, and (4) connects your answer to Psalm 139:14, which says, I will praise thee; for I am fearfully and wonderfully made. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why should teens avoid energy drinks and supplements? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Food, Water and Self Worth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Nutrients and MyPlate$j$, $j${"questions": [{"q": "Which nutrient is the body's main source of quick energy?", "options": ["Minerals", "Water", "Carbohydrates", "Fiber alone"]}, {"q": "Proteins mainly:", "options": ["Replace water", "Provide no value", "Store only vitamins", "Build and repair tissue"]}, {"q": "A gram of fat supplies about:", "options": ["4 calories", "0 calories", "20 calories", "9 calories"]}, {"q": "A MyPlate guide suggests filling about half your plate with:", "options": ["Sweets", "Soda", "Fruits and vegetables", "Fried foods"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Nutrients and MyPlate$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,2}'::int[], array[$j$Carbohydrates are the main quick fuel.$j$,$j$Muscles and other tissues are built and repaired with protein.$j$,$j$Carbohydrate and protein supply about 4 calories per gram.$j$,$j$Fruits and vegetables should fill about half the plate.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Nutrients and MyPlate$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Reading Food Labels$j$, $j${"questions": [{"q": "The first thing to check on a Nutrition Facts label is the:", "options": ["Color", "Brand name", "Serving size", "Price"]}, {"q": "A Percent Daily Value of 20 percent or more is generally considered:", "options": ["Zero", "Low", "High", "Unsafe"]}, {"q": "In an ingredient list, ingredients are listed:", "options": ["Alphabetically", "Randomly", "By price", "From greatest amount to least"]}, {"q": "Health experts advise teens to avoid:", "options": ["Energy drinks with high caffeine", "Milk", "Vegetables", "Water"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Reading Food Labels$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,0}'::int[], array[$j$All values on the label refer to one serving.$j$,$j$Five percent or less is low and 20 percent or more is high.$j$,$j$If sugar is first, the food contains more sugar than any other ingredient.$j$,$j$High caffeine can harm sleep and the heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Reading Food Labels$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Fueling and Hydration for Activity$j$, $j${"questions": [{"q": "A sign of good hydration is urine that is:", "options": ["Brown", "Bright orange", "Pale yellow", "Dark yellow"]}, {"q": "For most activities that last under an hour, the best drink is:", "options": ["Soda", "Energy drink", "Water", "Coffee"]}, {"q": "Which is an effect of dehydration?", "options": ["Headache and tiredness", "Better focus", "More energy", "Faster healing"]}, {"q": "A good snack after hard activity includes:", "options": ["Nothing at all", "Carbohydrates and protein", "Only candy", "Only caffeine"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Fueling and Hydration for Activity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,1}'::int[], array[$j$Pale yellow suggests that you are drinking enough.$j$,$j$Water is usually all that is needed.$j$,$j$Dehydration can cause fatigue, headache and cramps.$j$,$j$This combination helps muscles recover.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Fueling and Hydration for Activity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Healthy Habits, Body Image and Supplements$j$, $j${"questions": [{"q": "Fad diets and quick fixes are generally:", "options": ["Recommended for growing teens", "The best plan", "Unsafe and not lasting for teens", "Required"]}, {"q": "A worried student should first:", "options": ["Talk with a trusted adult, counselor or doctor", "Hide it", "Ignore warning signs", "Fast for a week"]}, {"q": "Supplements such as fat burners and pre workout products are:", "options": ["Required for athletes", "Always safe", "Not tested like medicines and can be harmful", "Approved for all teens"]}, {"q": "A healthy view of the body focuses on:", "options": ["Only appearance", "What it can do and how well you care for it", "Teasing others", "Comparing yourself with others"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Healthy Habits, Body Image and Supplements$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,1}'::int[], array[$j$Teens need regular meals to support growth.$j$,$j$Eating disorders are medical conditions that can be treated with help.$j$,$j$Ask a doctor before taking any supplement.$j$,$j$Every body is fearfully and wonderfully made.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Healthy Habits, Body Image and Supplements$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Nutrition and Hydration$j$, $j${"questions": [{"q": "Which nutrient is needed in small amounts and helps the body work?", "options": ["Vitamins and minerals", "Only fat", "Only salt", "Only sugar"]}, {"q": "A gram of protein supplies about:", "options": ["0 calories", "20 calories", "9 calories", "4 calories"]}, {"q": "MyPlate suggests choosing water and milk more often than:", "options": ["Fruit", "Vegetables", "Grains", "Sugary drinks"]}, {"q": "On a Nutrition Facts label, the numbers refer to:", "options": ["The whole package always", "One bite", "One day", "One serving"]}, {"q": "Dark yellow urine usually suggests:", "options": ["You need more fluid", "A broken bone", "Fast healing", "Perfect hydration"]}, {"q": "A good pre activity snack an hour before is:", "options": ["A banana or toast with peanut butter", "Nothing but caffeine", "A large greasy meal", "A giant dessert"]}, {"q": "An eating disorder is:", "options": ["A choice", "A serious medical illness that can be treated", "A sport", "A diet plan"]}, {"q": "Before taking any supplement, a teen should:", "options": ["Ask a friend only", "Mix several together", "Ask a doctor", "Order the strongest one"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Nutrition and Hydration$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,3,0,0,1,2}'::int[], array[$j$Vitamins and minerals support many body processes.$j$,$j$Protein and carbohydrate each supply about 4 calories per gram.$j$,$j$Sugary drinks add calories with few nutrients.$j$,$j$Check how many servings are in the package.$j$,$j$Pale yellow suggests good hydration.$j$,$j$Light carbohydrates give quick fuel.$j$,$j$Help is available and recovery is possible.$j$,$j$Supplements can be unsafe and are not tested like medicines.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Nutrition and Hydration$j$ on conflict (item_id) do nothing;
